   148	    /// <summary>
   149	    /// Reads the trailing `next offset: N` a job-output page always carries
   150	    /// (`SessionRuntime.JobCoreAsync`'s "output" case). A page without one is
   151	    /// treated as unknown rather than complete, so an unparseable page seals
   152	    /// incomplete instead of overclaiming.
   153	    /// </summary>
   154	    private static bool TryReadNextOffset(string page, out long nextOffset)
   155	    {
   156	        nextOffset = 0;
   157	        const string Marker = "next offset: ";
   158	        var start = page.LastIndexOf(Marker, StringComparison.Ordinal);
   159	        if (start < 0) return false;
   160	        var digits = page.AsSpan(start + Marker.Length);
   161	        var end = 0;
   162	        while (end < digits.Length && char.IsAsciiDigit(digits[end]))
   163	            end++;
   164	        return end > 0 && long.TryParse(digits[..end], out nextOffset);
   165	    }
